//! Display names, reasoning support, token limits and list prices of the models behind aho's llm
//! routes (`models.tsv`, generated by `scripts/models.py` from oh-my-pi's catalog). A route or
//! model that is not listed has no price: callers show token counts, never a guessed cost.
//!
//! The catalog also sizes requests. `model.max_tokens`, `model.thinking_budget` and
//! `model.context_window` resolve as: a value the operator set (any layer above the engineer's
//! Default/Bundle values) > the catalog's value for the selected model > the engineer default >
//! [`FALLBACK`]. [`limits`] is that rule for the session and the TUI; [`apply_catalog`] writes the
//! catalog values into the loadout (`Layer::Catalog`) so `aho explain` and the log show them.

use std::sync::LazyLock;

use aho_config::Loadout;
use aho_types::Usage;
use serde_json::Value;

/// USD per million tokens.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Price {
    pub input: f64,
    pub output: f64,
    pub cache_read: f64,
    pub cache_write: f64,
}

impl Price {
    /// The cost of `usage` in USD. Adapters report `input_tokens` without the cached part, so
    /// the four counts are disjoint.
    pub fn cost(&self, usage: &Usage) -> f64 {
        (usage.input_tokens as f64 * self.input
            + usage.output_tokens as f64 * self.output
            + usage.cache_read_tokens as f64 * self.cache_read
            + usage.cache_write_tokens as f64 * self.cache_write)
            / 1_000_000.0
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ModelInfo {
    pub route: &'static str,
    pub id: &'static str,
    pub name: &'static str,
    pub reasoning: bool,
    /// The window aho's requests get (Anthropic's without the 1M beta); `None`: not listed.
    pub context_window: Option<u64>,
    /// The provider's output-token ceiling; `None`: not listed.
    pub max_output: Option<u64>,
    pub price: Price,
}

const DATA: &str = include_str!("../models.tsv");

/// Sorted by `(route, id)` (the generator writes it so; rows that do not parse are dropped and a
/// test pins that there are none).
static MODELS: LazyLock<Vec<ModelInfo>> = LazyLock::new(|| DATA.lines().filter_map(row).collect());

fn row(line: &'static str) -> Option<ModelInfo> {
    if line.starts_with('#') || line.is_empty() {
        return None;
    }
    let mut f = line.split('\t');
    let (route, id, name, reasoning) = (f.next()?, f.next()?, f.next()?, f.next()?.parse().ok()?);
    let mut tokens = || f.next()?.parse::<u64>().ok().map(|n| (n > 0).then_some(n));
    let (context_window, max_output) = (tokens()?, tokens()?);
    let mut n = || f.next()?.parse::<f64>().ok().filter(|v| v.is_finite() && *v >= 0.0);
    let price = Price { input: n()?, output: n()?, cache_read: n()?, cache_write: n()? };
    Some(ModelInfo { route, id, name, reasoning, context_window, max_output, price })
}

/// The catalog entry of `model` on `route` (aho's `model.provider` / `model.name`).
pub fn lookup(route: &str, model: &str) -> Option<&'static ModelInfo> {
    let models: &'static [ModelInfo] = &MODELS;
    models.binary_search_by(|m| (m.route, m.id).cmp(&(route, model))).ok().map(|i| &models[i])
}

/// `model.provider` and `model.name`, with the core defaults when a loadout lacks them.
pub fn selected(l: &Loadout) -> (&str, &str) {
    (l.str("model.provider").unwrap_or("openai"), l.str("model.name").unwrap_or("gpt-4.1-mini"))
}

/// Per-request sizing of the selected model.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Limits {
    pub max_tokens: u32,
    /// Always below `max_tokens` (when that is non-zero): providers reject a larger budget.
    pub thinking_budget: u32,
    pub context_window: u64,
}

/// For a loadout without the core keys and a model the catalog does not list.
pub const FALLBACK: Limits = Limits { max_tokens: 8192, thinking_budget: 4096, context_window: 128_000 };
/// The most output tokens a catalog value asks for: a large edit fits, and one runaway answer
/// does not hold a turn for minutes.
pub const MAX_TOKENS_CAP: u64 = 64_000;
/// The most reasoning tokens a catalog-derived budget spends per request.
pub const THINKING_CAP: u64 = 16_384;

const MAX_TOKENS: &str = "model.max_tokens";
const THINKING_BUDGET: &str = "model.thinking_budget";
const CONTEXT_WINDOW: &str = "model.context_window";

/// The limits a session with loadout `l` runs with: operator > catalog > engineer default >
/// [`FALLBACK`] per key. The catalog's values are `context_window` as listed,
/// `max_tokens = min(max_output, 64000, context_window × (1 − compaction.threshold))` and
/// `thinking_budget = min(16384, max_tokens / 2)` for reasoning models (from the `max_tokens`
/// this function picked); the budget is clamped below `max_tokens`. The window clamp keeps
/// input + output inside the window until compaction fires (endpoints reject a request whose
/// prompt plus `max_tokens` exceeds it); an operator-set `max_tokens` is not clamped: whoever
/// set it chose that trade-off, and the provider's error names the key to lower.
pub fn limits(l: &Loadout) -> Limits {
    resolve(l).0
}

/// Ranks the catalog's values for the selected model into `l` as `Layer::Catalog`, replacing
/// those of an earlier model, so the loadout (and `aho explain`, and the log) says what
/// [`limits`] uses and where it came from.
pub fn apply_catalog(l: &mut Loadout) {
    let (route, model) = selected(l);
    let name = format!("{route}/{model}");
    let catalog = resolve(l).1;
    for (key, v) in catalog {
        l.derive(key, v.map(Value::from), &name);
    }
}

fn resolve(l: &Loadout) -> (Limits, [(&'static str, Option<u64>); 3]) {
    let (route, model) = selected(l);
    let info = lookup(route, model);
    let pick = |key: &str, catalog: Option<u64>, fallback: u64| {
        let (operator, engineer) = set_by(l, key);
        operator.or(catalog).or(engineer).unwrap_or(fallback)
    };
    let catalog_window = info.and_then(|m| m.context_window);
    let context_window = pick(CONTEXT_WINDOW, catalog_window, FALLBACK.context_window);
    let threshold = l.get("compaction.threshold").and_then(Value::as_f64).unwrap_or(0.8).clamp(0.0, 1.0);
    // The same rounding as the compaction trigger (`maintenance.rs`), so the two meet exactly.
    let headroom = context_window - ((context_window as f64 * threshold) as u64).min(context_window);
    // A zero headroom (threshold 1.0) leaves no catalog value: the engineer default applies.
    let catalog_max = info.and_then(|m| m.max_output).map(|n| n.min(MAX_TOKENS_CAP).min(headroom)).filter(|n| *n > 0);
    let max_tokens = pick(MAX_TOKENS, catalog_max, FALLBACK.max_tokens.into());
    let catalog_thinking = info.filter(|m| m.reasoning).map(|_| (max_tokens / 2).min(THINKING_CAP));
    let thinking = pick(THINKING_BUDGET, catalog_thinking, FALLBACK.thinking_budget.into());
    let thinking = if max_tokens > 0 { thinking.min(max_tokens - 1) } else { thinking };
    let to_u32 = |n: u64| u32::try_from(n).unwrap_or(u32::MAX);
    let limits = Limits { max_tokens: to_u32(max_tokens), thinking_budget: to_u32(thinking), context_window };
    (limits, [(MAX_TOKENS, catalog_max), (THINKING_BUDGET, catalog_thinking), (CONTEXT_WINDOW, catalog_window)])
}

/// `key`'s operator value (when the winner is an operator layer) and its engineer value (the
/// most specific Default/Bundle layer). A catalog value already in the loadout counts as
/// neither: it may be a previous model's.
fn set_by(l: &Loadout, key: &str) -> (Option<u64>, Option<u64>) {
    let Some(s) = l.config.get(key) else { return (None, None) };
    let operator = s.winner.layer.is_operator().then(|| s.value.as_u64()).flatten();
    let engineer = std::iter::once((&s.winner, &s.value))
        .chain(s.shadowed.iter().map(|(o, v)| (o, v)))
        .find(|(o, _)| matches!(o.layer, aho_config::Layer::Default | aho_config::Layer::Bundle(_)))
        .and_then(|(_, v)| v.as_u64());
    (operator, engineer)
}

#[cfg(test)]
mod tests {
    use super::*;
    use aho_config::{ConfigKey, Layer, ResolveInputs, Schema, Ty, resolve as resolve_config};
    use serde_json::json;

    #[test]
    fn every_row_parses_and_rows_are_sorted_for_lookup() {
        let rows = DATA.lines().filter(|l| !l.starts_with('#') && !l.is_empty()).count();
        assert_eq!(MODELS.len(), rows, "a row of models.tsv does not parse");
        assert!(MODELS.windows(2).all(|w| (w[0].route, w[0].id) < (w[1].route, w[1].id)), "models.tsv is not sorted by (route, id)");
    }

    #[test]
    fn lookup_is_exact_per_route_and_prices_cached_tokens_apart() {
        let m = lookup("anthropic", "claude-sonnet-4-5").expect("listed");
        assert_eq!(m.name, "Claude Sonnet 4.5");
        assert!(m.reasoning, "Sonnet 4.5 supports extended thinking");
        let u = Usage { input_tokens: 1_000_000, output_tokens: 100_000, cache_read_tokens: 2_000_000, cache_write_tokens: 0 };
        assert!((m.price.cost(&u) - (m.price.input + 0.1 * m.price.output + 2.0 * m.price.cache_read)).abs() < 1e-9);
        assert!(lookup("ollama", "claude-sonnet-4-5").is_none(), "no cross-route guess: a local route has no list price");
        assert!(lookup("anthropic", "claude-sonnet-4-5-unknown").is_none());
    }

    /// The core keys as `aho_cap::core_keys` declares them, resolved with `sets` as `--set` flags.
    fn loadout(sets: &[(&str, &str)]) -> Loadout {
        let mut schema = Schema::default();
        for (k, ty, d) in [
            ("model.provider", Ty::String, json!("openai")),
            ("model.name", Ty::String, json!("gpt-4.1-mini")),
            (MAX_TOKENS, Ty::Int, json!(8192)),
            (THINKING_BUDGET, Ty::Int, json!(4096)),
            (CONTEXT_WINDOW, Ty::Int, json!(128000)),
        ] {
            schema.add(ConfigKey::new(k, ty, Some(d), ""));
        }
        let inputs = ResolveInputs { sets: sets.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect(), ..Default::default() };
        resolve_config(&inputs, &schema, false).expect("resolves")
    }

    const SONNET: [(&str, &str); 2] = [("model.provider", "anthropic"), ("model.name", "claude-sonnet-4-5")];

    #[test]
    fn a_catalogued_model_without_operator_settings_gets_the_catalog_limits() {
        let l = loadout(&SONNET);
        let m = lookup("anthropic", "claude-sonnet-4-5").expect("listed");
        assert_eq!(m.max_output, Some(64_000));
        assert_eq!(
            limits(&l),
            Limits { max_tokens: 40_000, thinking_budget: 16_384, context_window: 200_000 },
            "64000 output tokens would overflow 200k for inputs between 136k and the 160k compaction point"
        );
        let gpt5 = loadout(&[("model.provider", "openai"), ("model.name", "gpt-5")]);
        assert_eq!(limits(&gpt5).max_tokens, 64_000, "a 128k output ceiling in a 400k window is capped at {MAX_TOKENS_CAP}");
        let mini = loadout(&[]);
        assert_eq!(limits(&mini).context_window, 1_047_576, "the default model's listed window, not 128000");
    }

    #[test]
    fn derived_output_leaves_the_input_room_compaction_guarantees() {
        let row = [("model.provider", "openrouter"), ("model.name", "essentialai/rnj-1-instruct")];
        let m = lookup(row[0].1, row[1].1).expect("listed");
        assert_eq!((m.context_window, m.max_output), (Some(32_768), Some(32_768)), "a row whose output ceiling is its whole window");
        assert_eq!(limits(&loadout(&row)).max_tokens, 6_554, "the window's 20% above the 0.8 compaction threshold");
        for m in MODELS.iter().filter(|m| m.max_output.is_some() && m.context_window.is_some()) {
            let got = limits(&loadout(&[("model.provider", m.route), ("model.name", m.id)]));
            let compacts_at = (got.context_window as f64 * 0.8) as u64;
            assert!(compacts_at + u64::from(got.max_tokens) <= got.context_window, "{}/{}: {got:?}", m.route, m.id);
        }

        let mut l = loadout(&SONNET);
        l.config.insert("compaction.threshold".into(), aho_config::Sourced { value: json!(0.9), ..l.config["model.name"].clone() });
        assert_eq!(limits(&l).max_tokens, 20_000, "an earlier-compacting threshold leaves more room, a later one less");
        let mut sets = SONNET.to_vec();
        sets.push((MAX_TOKENS, "64000"));
        assert_eq!(limits(&loadout(&sets)).max_tokens, 64_000, "an operator value is the operator's call, not clamped");
        sets.push((CONTEXT_WINDOW, "100000"));
        sets.retain(|(k, _)| *k != MAX_TOKENS);
        assert_eq!(limits(&loadout(&sets)).max_tokens, 20_000, "the clamp follows the window the session uses");
    }

    #[test]
    fn anthropic_windows_are_capped_at_the_window_aho_requests_get() {
        let over = MODELS.iter().filter(|m| m.route == "anthropic").filter(|m| m.context_window.is_some_and(|w| w > 200_000));
        assert_eq!(over.count(), 0, "aho sends no 1M-context beta header");
        assert!(MODELS.iter().any(|m| m.route != "anthropic" && m.context_window.is_some_and(|w| w > 200_000)));
    }

    #[test]
    fn an_operator_value_wins_over_the_catalog_and_sizes_the_derived_thinking_budget() {
        let mut sets = SONNET.to_vec();
        sets.extend([(MAX_TOKENS, "10000"), (CONTEXT_WINDOW, "150000")]);
        let l = loadout(&sets);
        assert_eq!(limits(&l), Limits { max_tokens: 10_000, thinking_budget: 5_000, context_window: 150_000 });
        sets.push((THINKING_BUDGET, "2048"));
        assert_eq!(limits(&loadout(&sets)).thinking_budget, 2048);
    }

    #[test]
    fn an_unknown_model_falls_back_to_the_engineer_defaults() {
        let l = loadout(&[("model.provider", "ollama"), ("model.name", "qwen3:32b")]);
        assert_eq!(limits(&l), FALLBACK);
        let mut schema = Schema::default();
        schema.add(ConfigKey::new("model.provider", Ty::String, None, ""));
        let inputs = ResolveInputs { sets: vec![("model.provider".into(), "ollama".into())], ..Default::default() };
        let bare = resolve_config(&inputs, &schema, false).expect("resolves");
        assert_eq!(limits(&bare), FALLBACK, "no limit keys at all: the built-in fallback");
    }

    #[test]
    fn the_thinking_budget_stays_below_max_tokens() {
        for m in MODELS.iter().filter(|m| m.reasoning) {
            let l = loadout(&[("model.provider", m.route), ("model.name", m.id)]);
            let got = limits(&l);
            assert!(got.thinking_budget < got.max_tokens, "{}/{}: {got:?}", m.route, m.id);
        }
        let mut sets = SONNET.to_vec();
        sets.extend([(MAX_TOKENS, "4000"), (THINKING_BUDGET, "9000")]);
        assert_eq!(limits(&loadout(&sets)).thinking_budget, 3999, "an operator budget above max_tokens is clamped");
    }

    #[test]
    fn applied_catalog_values_say_where_they_came_from_and_follow_a_model_change() {
        let mut l = loadout(&SONNET);
        apply_catalog(&mut l);
        let s = &l.config[MAX_TOKENS];
        assert_eq!((s.value.clone(), s.winner.layer.clone()), (json!(40_000), Layer::Catalog("anthropic/claude-sonnet-4-5".into())));
        assert_eq!(limits(&l), Limits { max_tokens: 40_000, thinking_budget: 16_384, context_window: 200_000 });

        // A runtime model switch (a subagent's `model`) leaves the old catalog values behind
        // until re-applied; `limits` already ignores them.
        let old = l.config["model.name"].clone();
        l.config.insert("model.name".into(), aho_config::Sourced { value: json!("qwen3:32b"), ..old.clone() });
        l.config.insert("model.provider".into(), aho_config::Sourced { value: json!("ollama"), ..old });
        assert_eq!(limits(&l), FALLBACK);
        apply_catalog(&mut l);
        assert_eq!(l.config[MAX_TOKENS].winner.layer, Layer::Default);
        assert_eq!(l.get(MAX_TOKENS), Some(&json!(8192)));
    }
}
